import hmac
import hashlib
import os
import time
import sqlite3
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['DATABASE'] = ':memory:'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        api_key_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        classification TEXT NOT NULL DEFAULT 'internal'
    )''')
    # Seed data
    admin_key = hashlib.sha256(b'admin-secret-key-do-not-share').hexdigest()
    user_key = hashlib.sha256(b'user-key-12345').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (id, username, api_key_hash, role) VALUES (1, 'admin', ?, 'admin')", (admin_key,))
    db.execute("INSERT OR IGNORE INTO users (id, username, api_key_hash, role) VALUES (2, 'alice', ?, 'user')", (user_key,))
    db.execute("INSERT OR IGNORE INTO documents (id, owner_id, title, content, classification) VALUES (1, 1, 'Secret Plan', 'Top secret content here', 'top_secret')")
    db.execute("INSERT OR IGNORE INTO documents (id, owner_id, title, content, classification) VALUES (2, 2, 'Alice Notes', 'Regular notes', 'internal')")
    db.commit()

def compute_api_signature(api_key, timestamp, body):
    """Compute HMAC signature for API authentication."""
    message = f"{timestamp}:{body}".encode('utf-8')
    return hmac.new(api_key.encode('utf-8'), message, hashlib.sha256).hexdigest()

def verify_signature(provided_sig, expected_sig):
    """Constant-time signature verification to prevent timing attacks."""
    if not provided_sig or not expected_sig:
        return False
    # Ensure both are the same type for constant-time comparison
    if isinstance(provided_sig, bytes):
        provided_sig = provided_sig.decode('utf-8', errors='replace')
    if isinstance(expected_sig, bytes):
        expected_sig = expected_sig.decode('utf-8', errors='replace')
    return hmac.compare_digest(provided_sig, expected_sig)

def authenticate_request(f):
    """Decorator to authenticate API requests using HMAC signatures."""
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        timestamp = request.headers.get('X-Timestamp', '')
        signature = request.headers.get('X-Signature', '')

        if not all([api_key, timestamp, signature]):
            return jsonify({'error': 'Missing authentication headers'}), 401

        # Check timestamp freshness (5 minute window)
        try:
            req_time = int(timestamp)
            current_time = int(time.time())
            if abs(current_time - req_time) > 300:
                return jsonify({'error': 'Request expired'}), 401
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid timestamp'}), 401

        db = get_db()
        # Hash the provided key and look up user
        key_hash = hashlib.sha256(api_key.encode('utf-8')).hexdigest()
        user = db.execute('SELECT * FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()

        if not user:
            return jsonify({'error': 'Invalid API key'}), 401

        # Verify HMAC signature
        body = request.get_data(as_text=True) or ''
        expected = compute_api_signature(api_key, timestamp, body)

        if not verify_signature(signature, expected):
            return jsonify({'error': 'Invalid signature'}), 401

        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    """Authorization decorator - checks user role."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user['role'] != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/documents', methods=['GET'])
@authenticate_request
def list_documents():
    """List documents accessible to the current user."""
    db = get_db()
    user = g.current_user

    if user['role'] == 'admin':
        docs = db.execute('SELECT id, title, classification FROM documents').fetchall()
    else:
        docs = db.execute(
            'SELECT id, title, classification FROM documents WHERE owner_id = ? OR classification = ?',
            (user['id'], 'public')
        ).fetchall()

    return jsonify({'documents': [dict(d) for d in docs]})

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@authenticate_request
def get_document(doc_id):
    """Get a specific document with authorization check."""
    db = get_db()
    user = g.current_user
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()

    if not doc:
        return jsonify({'error': 'Not found'}), 404

    # Authorization: admin can see all, users can see own + public
    if user['role'] != 'admin' and doc['owner_id'] != user['id'] and doc['classification'] != 'public':
        return jsonify({'error': 'Access denied'}), 403

    return jsonify({'document': dict(doc)})

@app.route('/api/admin/users', methods=['GET'])
@authenticate_request
@require_role('admin')
def list_users():
    """Admin endpoint to list all users."""
    db = get_db()
    users = db.execute('SELECT id, username, role FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(debug=False)
